// ============================================================================
// 27. $Range.toList
// ============================================================================
TEST(BuiltinTests, RangeToList) {
  auto res = run_ifjcode(R"(
LABEL $$test_main
DEFVAR GF@trash

# (1 to 5).toList -> List(1, 2, 3, 4, 5)
PUSHS int@1
PUSHS int@5
CALL to
CALL toList
CALL print
POPS GF@trash
WRITE string@\010

# (1 until 5).toList -> List(1, 2, 3, 4)
PUSHS int@1
PUSHS int@5
CALL until
CALL toList
CALL print
POPS GF@trash
WRITE string@\010

# (5 to 1 by -2).toList -> List(5, 3, 1)
PUSHS int@5
PUSHS int@1
CALL to
PUSHS int@-2
CALL by
CALL toList
CALL print
POPS GF@trash
WRITE string@\010

# (5 until 1 by -2).toList -> List(5, 3)
PUSHS int@5
PUSHS int@1
CALL until
PUSHS int@-2
CALL by
CALL toList
CALL print
POPS GF@trash
WRITE string@\010

# (5 to 5).toList -> List(5)
PUSHS int@5
PUSHS int@5
CALL to
CALL toList
CALL print
POPS GF@trash
WRITE string@\010

# (5 until 5).toList -> List()
PUSHS int@5
PUSHS int@5
CALL until
CALL toList
CALL print
POPS GF@trash
WRITE string@\010

# (1 to 5 by -1).toList -> List()
PUSHS int@1
PUSHS int@5
CALL to
PUSHS int@-1
CALL by
CALL toList
CALL print
POPS GF@trash
EXIT int@0
)");

  EXPECT_EQ(res.exit_code, 0) << res.output;
  EXPECT_EQ(res.output, "List(1, 2, 3, 4, 5)\n"
                        "List(1, 2, 3, 4)\n"
                        "List(5, 3, 1)\n"
                        "List(5, 3)\n"
                        "List(5)\n"
                        "List()\n"
                        "List()");
}